'use client';
/* Molecular SVGs are generated by the local API; they do not need image optimization. */
/* eslint-disable @next/next/no-img-element */
import { useEffect, useRef, useState } from 'react';
import { api, base, type Campaign, type CampaignSummary, type Preview, type Score, type Job } from '@/lib/campaign-api';
import { ProteinScene, ThinkingScene, DockingView } from './Scenes';
import './workflow.css';

const steps=['Set up','Predict','Select','Results','Learn'] as const;
type Step=typeof steps[number];
const short=(id:string)=>id.replace('CHEMBL238_Ki:','DAT-');
const fmt=(n:number|null|undefined)=>n==null?'—':n.toFixed(2);
const message=(e:unknown)=>e instanceof Error?e.message:'Something went wrong. Please try again.';
const stages=[['Read the evidence','Known compounds and assay measurements'],['Encode the chemistry','Molecular structures → fingerprint features'],['Fit the relationship','Learn from observed measurements'],['Score the candidates','Estimate activity for untested compounds'],['Prepare your shortlist','Rank predictions for your review']];

export default function CampaignWorkflow(){
 const [campaigns,setCampaigns]=useState<CampaignSummary[]>([]),[campaign,setCampaign]=useState<Campaign|null>(null),[preview,setPreview]=useState<Preview|null>(null);
 const [step,setStep]=useState<Step>('Set up'),[budget,setBudget]=useState(8),[library,setLibrary]=useState('all'),[selected,setSelected]=useState<string[]>([]),[active,setActive]=useState('');
 const [compare,setCompare]=useState<string[]>([]),[comparison,setComparison]=useState<'properties'|'docking'|null>(null),[tableTab,setTableTab]=useState('batch'),[search,setSearch]=useState('');
 const [busy,setBusy]=useState(''),[error,setError]=useState(''),[loading,setLoading]=useState(true),[stage,setStage]=useState(0),[resultMode,setResultMode]=useState('replay'),[updated,setUpdated]=useState(false),[before,setBefore]=useState<Record<string,number>>({});
 const animationSkip=useRef(false),generation=useRef(0),dialog=useRef<HTMLDialogElement>(null),stageTimer=useRef<ReturnType<typeof setInterval>|null>(null),alive=useRef(true);
 const latest=campaign?.rounds.at(-1),pending=campaign?.rounds.find(r=>r.status==='pending');
 const fresh=!!preview&&preview.revision===campaign?.revision&&!pending;
 const available=campaign?.compounds.filter(c=>c.status==='available'&&c.constraint!=='excluded')||[];
 const measured=campaign?.compounds.filter(c=>c.status==='measured')||[];
 const scores=preview?.scored||[];
 const ranked=scores.filter(s=>available.some(c=>c.compound_id===s.compound_id)&&(library==='all'||s.similarity>=.35||s.constraint==='locked')).sort((a,b)=>b.prediction-a.prediction||a.compound_id.localeCompare(b.compound_id));
 const inspected=campaign?.compounds.find(c=>c.compound_id===active),score=scores.find(s=>s.compound_id===active);
 const records=latest?.recommendations||[];
 const measuredResults=records.filter(r=>latest?.results[r.compound_id]?.status==='measured'&&latest.results[r.compound_id].value!=null);
 const mae=measuredResults.length?measuredResults.reduce((sum,r)=>sum+Math.abs(r.prediction-latest!.results[r.compound_id].value!),0)/measuredResults.length:null;
 function molecule(id:string){return `${base}/campaigns/${campaign!.id}/molecule?compound_id=${encodeURIComponent(id)}`;}
 async function list(){const rows=await api<CampaignSummary[]>('/campaigns');if(alive.current)setCampaigns(rows);return rows;}
 async function load(id:string){const token=++generation.current;setLoading(true);setError('');try{const c=await api<Campaign>(`/campaigns/${id}`);if(token!==generation.current||!alive.current)return;setCampaign(c);setPreview(null);setSelected([]);setCompare([]);setActive('');setUpdated(false);setBefore({});setLibrary('all');setResultMode(c.demo?'replay':'lab');localStorage.setItem('aster-campaign',id);setStep(c.rounds.some(r=>r.status==='pending')?'Results':'Set up');
 const pid=localStorage.getItem(`aster-workflow-preview-${id}`)||c.rounds.at(-1)?.preview_id;
 if(pid){try{const p=await api<Preview>(`/campaigns/${id}/previews/${pid}`);if(token!==generation.current)return;setPreview(p);setBefore(Object.fromEntries(p.scored.map(s=>[s.compound_id,s.prediction])));if(p.revision===c.revision){setSelected(p.recommendations.map(r=>r.compound_id));setActive(p.recommendations[0]?.compound_id||'');setBudget(p.recommendations.length);}}catch{/* A removed preview is safely replaced by a new fit. */}}
 }catch(e){if(token===generation.current)setError(message(e));}finally{if(token===generation.current)setLoading(false);}}
 useEffect(()=>{alive.current=true;list().then(rows=>{if(!alive.current)return;const last=localStorage.getItem('aster-campaign');if(rows.length)void load(rows.find(r=>r.id===last)?.id||rows[0].id);else setLoading(false);}).catch(e=>{if(alive.current){setError(message(e));setLoading(false);}});return()=>{alive.current=false;if(stageTimer.current)clearInterval(stageTimer.current);};},[]); // Initial campaign recovery only.
 useEffect(()=>{if(comparison)dialog.current?.showModal();else dialog.current?.close();},[comparison]);
 async function perform(label:string,fn:()=>Promise<void>){setBusy(label);setError('');try{await fn();}catch(e){setError(message(e));}finally{if(alive.current)setBusy('');}}
 async function createDemo(){await perform('Loading public campaign',async()=>{const r=await api<{id:string}>('/demo',{});await list();await load(r.id);});}
 async function refresh(){if(!campaign)return;const c=await api<Campaign>(`/campaigns/${campaign.id}`);setCampaign(c);await list();return c;}
 async function predict(learning=false){if(!campaign||pending)return;const token=++generation.current,started=Date.now();animationSkip.current=learning;setError('');setBusy('Fitting model');setStage(0);if(!learning)setStep('Predict');setUpdated(false);
 if(stageTimer.current)clearInterval(stageTimer.current);stageTimer.current=setInterval(()=>setStage(s=>Math.min(4,s+1)),1250);
 try{let jid=localStorage.getItem(`aster-job-${campaign.id}`);if(jid){try{const old=await api<Job>(`/jobs/${jid}`);if(old.status==='failed')jid=null;}catch{jid=null;}}
 if(!jid){const j=await api<{job_id:string}>(`/campaigns/${campaign.id}/previews`,{batch_size:Math.min(budget,available.length)});jid=j.job_id;localStorage.setItem(`aster-job-${campaign.id}`,jid);}
 let result:Preview|undefined;
 for(let i=0;i<240;i++){if(token!==generation.current||!alive.current)return;const job=await api<Job>(`/jobs/${jid}`);if(job.status==='failed')throw Error(job.error||'Prediction failed');if(job.status==='complete'&&job.preview_id){result=await api<Preview>(`/campaigns/${campaign.id}/previews/${job.preview_id}`);break;}await new Promise(r=>setTimeout(r,500));}
 while(!learning&&!animationSkip.current&&Date.now()-started<6000&&alive.current)await new Promise(r=>setTimeout(r,100));
 if(!result)throw Error('The fit is still running. Retry to reconnect to the saved job.');if(token!==generation.current||!alive.current)return;
 if(result.revision!==campaign.revision){localStorage.removeItem(`aster-job-${campaign.id}`);throw Error('Campaign changed. Reload before starting a fresh prediction.');}
 localStorage.removeItem(`aster-job-${campaign.id}`);localStorage.setItem(`aster-workflow-preview-${campaign.id}`,result.id);setPreview(result);
 const eligible=result.scored.filter(s=>s.constraint!=='excluded'&&(library==='all'||s.similarity>=.35||s.constraint==='locked')).sort((a,b)=>b.prediction-a.prediction);
 const locked=eligible.filter(s=>s.constraint==='locked'),rest=eligible.filter(s=>s.constraint!=='locked');const chosen=[...locked,...rest].slice(0,Math.min(budget,result.recommendations.length)).map(s=>s.compound_id);
 setSelected(chosen);setActive(chosen[0]||eligible[0]?.compound_id||'');setStage(5);if(learning)setUpdated(true);
 }catch(e){if(token===generation.current){setError(message(e));if(!message(e).includes('still running'))localStorage.removeItem(`aster-job-${campaign.id}`);}}finally{if(token===generation.current){setBusy('');if(stageTimer.current)clearInterval(stageTimer.current);}}
 }
 function navigate(next:Step){if(busy)return;setError('');if((next==='Select'||next==='Predict')&&pending){setStep('Results');return;}if(next==='Select'&&!fresh){void predict();return;}if(next==='Predict'){void predict();return;}if((next==='Results'||next==='Learn')&&!latest){setError('Choose and save a batch from Select first.');return;}if(next==='Learn'&&pending){setStep('Results');return;}setStep(next);}
 function toggle(id:string){if(!fresh||busy)return;const c=campaign?.compounds.find(c=>c.compound_id===id);if(c?.constraint==='locked'){setError('This compound has a saved lock and must remain in the batch.');return;}setError('');if(selected.includes(id))setSelected(selected.filter(v=>v!==id));else if(selected.length<Math.min(budget,preview!.recommendations.length))setSelected([...selected,id]);else setError('Your batch is full. Remove a compound before adding another.');}
 function toggleCompare(id:string){if(compare.includes(id))setCompare(compare.filter(c=>c!==id));else if(compare.length<3)setCompare([...compare,id]);else setError('Compare up to three compounds at a time.');}
 async function commit(){if(!campaign||!fresh||!selected.length)return;await perform('Saving your batch',async()=>{await api(`/campaigns/${campaign.id}/commit`,{preview_id:preview!.id,selected_ids:selected});setBefore(Object.fromEntries(scores.map(s=>[s.compound_id,s.prediction])));await refresh();setUpdated(false);setStep('Results');});}
 async function reveal(){if(!campaign||!latest)return;await perform('Revealing public measurements',async()=>{await api(`/campaigns/${campaign.id}/rounds/${latest.round}/demo-results`,{});await refresh();});}
 async function importResults(file:File){if(!campaign||!latest)return;await perform('Importing results',async()=>{if(file.size>2_000_000)throw Error('Use a CSV smaller than 2 MB.');let csv=await file.text();if(csv.split(/\r?\n/)[0].trim()==='compound_id,value'){csv='compound_id,status,value\n'+csv.trim().split(/\r?\n/).slice(1).map(line=>{const [id,value,...extra]=line.split(',');if(extra.length)throw Error('Use the exported result template.');return `${id},measured,${value}`;}).join('\n');}await api(`/campaigns/${campaign.id}/rounds/${latest.round}/results`,{csv});await refresh();});}
 const displayScores=ranked.filter(s=>(tableTab==='all'||selected.includes(s.compound_id))&&s.compound_id.toLowerCase().includes(search.toLowerCase()));
 return <div className="workflow-root"><header className="app-header"><button className="brand" onClick={()=>navigate('Set up')} disabled={!!busy} aria-label="Aster home"><span className="brand-symbol">☼</span><strong>aster</strong><span className="brand-divider"/><span>{campaign?.demo?'Dopamine transporter':campaign?.name||'New campaign'}</span></button><nav id="steps" aria-label="Campaign steps">{steps.map((s,i)=><button key={s} className={`step ${step===s?'active':''}`} aria-current={step===s?'step':undefined} disabled={!!busy||!campaign&&s!=='Set up'} onClick={()=>navigate(s)}><span>{String(i+1).padStart(2,'0')}</span>{s}</button>)}</nav><span className="workflow-status">{busy||'Saved campaign workspace'}</span></header>
 {error&&<div className="workflow-error" role="alert">{error}<button onClick={()=>setError('')} aria-label="Dismiss message">×</button></div>}
 {loading?<main className="loading">Loading your campaign…</main>:<main>
 {step==='Set up'&&<div className="page"><div className="page-heading"><span className="eyebrow">A new discovery loop</span><h1>What do you want to discover?</h1><p>Choose the biological question, the compounds to explore, and how many you want to test.</p></div><div className="setup-grid"><div className="setup-left"><section className="section-card"><div className="section-label"><span>01</span><h3>Choose your target</h3></div>{campaign?<><label className="campaign-field">Campaign<select aria-label="Campaign" value={campaign.id} disabled={!!busy} onChange={e=>void load(e.target.value)}>{campaigns.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><div className="target-field"><span className="target-icon">⌬</span><div><strong>{campaign.demo?'Human dopamine transporter':campaign.name}</strong><small>{campaign.demo?'SLC6A3 · DAT · Homo sapiens':campaign.assay}</small></div></div><div className="setting-row"><span>What are we predicting?</span><span className="badge purple">Binding potency · {campaign.endpoint}</span></div><p className="target-note">Higher {campaign.endpoint} means stronger measured activity in this assay. The model learns from molecular fingerprints and known measurements.</p></>:<><p className="target-note">Start with human DAT: one public assay, measured compounds, and a candidate library.</p><button className="btn primary" disabled={!!busy} onClick={createDemo}>Start a public DAT campaign →</button></>}</section><section className="section-card"><div className="section-label"><span>02</span><h3>Choose your compound library</h3></div><div className="choice-row">{[['all','Explore the full library','All eligible compounds'],['near','Stay near known chemistry','Similarity ≥ 0.35 after scoring']].map(([value,title,description])=><button key={value} className={`choice ${library===value?'active':''}`} onClick={()=>{setLibrary(value);setPreview(null);}} disabled={!!busy}><strong>{title}</strong><small>{description}</small></button>)}</div><div className="count-strip"><div><strong>{measured.length}</strong><span>known measurements</span></div><div><strong>{available.length}</strong><span>eligible candidates</span></div><div><strong>1</strong><span>consistent assay</span></div></div><p className="target-note">Saved exclusions and locked compounds are respected.</p></section><section className="section-card"><div className="section-label"><span>03</span><h3>Set the size of your next step</h3></div><div className="setting-row"><span>Compounds in this batch</span><input className="budget-input" aria-label="Batch size" type="number" min="1" max={Math.min(64,available.length)||64} value={budget} onChange={e=>{setBudget(Number(e.target.value));setPreview(null);}}/></div><p className="target-note">Start with the highest predictions, then make the final selection yourself.</p></section></div><aside>{campaign?.demo&&<div className="protein-card"><ProteinScene overview/><span className="protein-tag">STRUCTURAL CONTEXT / 8Y2G</span><div className="protein-bottom"><span>Experimental protein backbone</span><span>Drag to rotate ↔</span></div></div>}<div className="summary-card"><h3>Your campaign, at a glance</h3><div className="summary-line"><span>Prediction</span><span>{campaign?.endpoint||'pKi'}</span></div><div className="summary-line"><span>Model</span><span>Morgan + ridge</span></div><div className="summary-line"><span>Batch size</span><span>{budget} compounds</span></div><div className="summary-note"><span>◷</span><span><strong>No lab? Start with a replay.</strong><br/>Reveal existing public measurements and watch the model learn. No new experiment is implied.</span></div>{campaign&&<button className="btn small" disabled={!!busy} onClick={createDemo}>Start a fresh public campaign</button>}</div></aside></div><div className="setup-actions"><small>Campaigns, committed batches, and results are saved locally.</small>{campaign&&<button className="btn primary" disabled={!!busy||!pending&&(!Number.isInteger(budget)||budget<1||budget>64||budget>available.length)} onClick={()=>pending?setStep('Results'):void predict()}>{pending?'Continue pending results':'Start predicting'} →</button>}</div></div>}
 {step==='Predict'&&<section className="predict-page"><div className="predict-heading"><div><span className="eyebrow">Round {preview?.round||((latest?.round||0)+1)} / Predict</span><h1>{stage===5?'A starting point. The choice is yours.':'From known chemistry to new possibilities.'}</h1><p>{campaign?.demo?'Human DAT':campaign?.name} · {measured.length} measurements · {available.length} candidates</p></div><span className="badge purple">Morgan + ridge</span></div><div className="predict-layout"><div className="process-list">{stages.map(([title,desc],i)=><div key={title} className={`process-step ${i===Math.min(stage,4)?'active':''} ${i<stage?'complete':''}`}><span>{i<stage?'✓':i+1}</span><div><strong>{title}</strong><small>{desc}</small></div></div>)}</div><div className="thinking-scene"><ThinkingScene stage={stage}/><div className="scene-caption">CHEMICAL STRUCTURES → MOLECULAR FEATURES → PREDICTIONS</div></div><aside className="process-readout"><span>{stage===5?'READY FOR REVIEW':'OBSERVED EVIDENCE'}</span><div className="readout-number">{stage===5?scores.length:measured.length}</div><p>{stage===5?'Inspect the evidence and build the batch you want to test.':'Measured assay outcomes provide the training signal.'}</p><div className="signal-bars">{[18,31,22,45,29,39,50,36].map((h,i)=><i key={i} style={{height:h,animationDelay:`${i*.13}s`}}/>)}</div></aside></div><div className="predict-footer"><div className="progress-track"><i style={{width:`${stage===5?100:10+stage*20}%`}}/></div><div className="between"><span role="status">{busy?'Fitting and scoring…':stage===5?'Scoring complete. Your workspace is ready.':'The fit needs attention.'}</span>{busy&&<button className="btn small" onClick={()=>{animationSkip.current=true;}}>Skip animation</button>}<button className="btn primary" disabled={!!busy} onClick={()=>stage===5?setStep('Select'):void predict()}>{stage===5?'Select compounds →':'Retry prediction'}</button></div><p className="playback-note">Animation explains the workflow; it does not report internal model reasoning or compute timing. Predictions come from the saved model fit.</p></div></section>}
 {step==='Select'&&campaign&&<section className="selection-shell"><div className="selection-toolbar"><h2>{campaign.demo?'Human DAT':campaign.name} <span>/ Round {preview?.round} · Choose your next batch</span></h2><div className="flex"><button className="btn small" onClick={()=>{const locked=ranked.filter(s=>s.constraint==='locked'),rest=ranked.filter(s=>s.constraint!=='locked');setSelected([...locked,...rest].slice(0,Math.min(budget,preview?.recommendations.length||0)).map(s=>s.compound_id));}}>Restore top {budget}</button></div></div><div className="selection-main"><section className="protein-stage"><div className="inline-docking"><div className="map-heading"><h3>{short(active)} · Structural evidence</h3></div>{active&&<DockingView key={`${campaign.id}:${active}`} campaignId={campaign.id} compoundId={active} demo={campaign.demo}/>}<p className="map-note">Drag to rotate · Scroll to zoom. Experimental DAT: 8Y2G. Docking poses are hypotheses, not binding measurements.</p></div></section><section className="map-panel floating-map"><div className="map-heading"><h3>Candidate map</h3><span>{ranked.length} candidates · {measured.length} measured</span></div><div className="legend"><span>● Untested</span><span>▪ Measured</span><span className="purple">○ In your batch</span></div><div className="map-chart"><CandidateMap scores={ranked} measured={measured.map(c=>({id:c.compound_id,value:c.value!}))} selected={selected} active={active} endpoint={campaign.endpoint} onSelect={setActive}/></div><p className="map-note">Select a point to inspect. Novelty is chemical distance, not calibrated uncertainty.</p></section><aside className="inspector">{inspected?<><div className="inspector-top"><span>{selected.includes(active)?'In your batch':'Available candidate'} · {selected.length} selected</span><span className="badge purple">{selected.includes(active)?'Selected':'Inspect'}</span></div><h2 className="compound-id">{short(active)}</h2><div className="molecule-box"><img src={molecule(active)} alt={`${short(active)} molecular structure`}/><MoleculeProperties key={active} campaignId={campaign.id} compoundId={active}/></div><div className="inspector-score"><span>Predicted {campaign.endpoint}</span><strong>{fmt(score?.prediction)}</strong></div><div className="nearest-row"><span>Nearest measured</span><div className="mono">{short(score?.nearest_measured_id||'—')} · sim {fmt(score?.similarity)}<br/>Observed {fmt(score?.nearest_measured_value)} {campaign.endpoint}</div></div><div className="rationale"><span>What the evidence says</span><p>Inspect predicted activity alongside its nearest measured analog. {fmt((score?.similarity||0)*100)}% fingerprint similarity describes chemical resemblance, not confidence in the prediction.</p></div><div className="inspector-actions"><button className={`btn ${selected.includes(active)?'soft':''}`} disabled={!fresh||!!busy} onClick={()=>toggle(active)}>{selected.includes(active)?'✓ In batch · remove':'+ Add to batch'}</button></div></>:<p>Select a candidate from the map or table.</p>}</aside><section className="batch-panel"><div className="batch-toolbar"><div className="table-tabs"><button className={tableTab==='batch'?'active':''} onClick={()=>setTableTab('batch')}>Your batch <span>{selected.length}</span></button><button className={tableTab==='all'?'active':''} onClick={()=>setTableTab('all')}>All candidates <span>{ranked.length}</span></button></div><input className="table-search" aria-label="Find a compound" placeholder="Find a compound…" value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="table-scroll"><table><thead><tr><th>Select</th><th>Compound</th><th>Predicted {campaign.endpoint}</th><th>Nearest similarity</th><th>Evidence</th><th>Compare</th></tr></thead><tbody>{displayScores.map(s=><tr key={s.compound_id} className={active===s.compound_id?'selected-row':''}><td><input type="checkbox" aria-label={`Select ${short(s.compound_id)}`} checked={selected.includes(s.compound_id)} onChange={()=>toggle(s.compound_id)} disabled={!fresh||!!busy||s.constraint==='locked'}/></td><td><button className="mono" onClick={()=>setActive(s.compound_id)}>{short(s.compound_id)}</button></td><td className="mono">{fmt(s.prediction)}</td><td className="mono">{fmt(s.similarity)}</td><td>{s.constraint==='locked'?'Saved lock':'Measured analog available'}</td><td><button className="btn small" aria-pressed={compare.includes(s.compound_id)} aria-label={`${compare.includes(s.compound_id)?'Remove':'Add'} ${short(s.compound_id)} ${compare.includes(s.compound_id)?'from':'to'} comparison`} disabled={compare.length===3&&!compare.includes(s.compound_id)} onClick={()=>toggleCompare(s.compound_id)}>{compare.includes(s.compound_id)?'Remove':'+ Add'}</button></td></tr>)}</tbody></table>{!displayScores.length&&<p className="empty-table">{ranked.length?'No matches. Use All candidates to add compounds.':'No eligible compounds in this scope. Try the full library in Set up.'}</p>}</div></section></div><footer className="selection-footer">{compare.length>0&&<section className="comparison-selection" aria-label="Selected for comparison"><div className="comparison-selection-info"><strong role="status">{compare.length} of 3 selected for comparison</strong><span>{compare.length===1?'Add one more compound to compare side by side.':'Ready to compare structures side by side.'}</span></div><div className="comparison-chips">{compare.map(id=><button key={id} className="comparison-chip" aria-label={`Remove ${short(id)} from comparison`} onClick={()=>toggleCompare(id)}>{short(id)} <span aria-hidden="true">×</span></button>)}</div><button className="btn primary" disabled={compare.length<2} onClick={()=>setComparison('properties')}>Open comparison ({compare.length}) →</button></section>}<span>{selected.length} of {budget} slots selected · Round {preview?.round}</span><div className="flex"><button className="btn small" onClick={()=>navigate('Set up')}>Edit settings</button><button className="btn primary" disabled={!fresh||!selected.length||!!busy} onClick={commit}>{busy||`Continue with ${selected.length} compounds →`}</button></div></footer></section>}
 {step==='Results'&&campaign&&latest&&<div className="page"><div className="page-heading"><span className="eyebrow">Round {latest.round} / Results</span><h1>{latest.status==='complete'?'The observations are in.':'A batch chosen. What happens next?'}</h1><p>Compare what the model expected with what was measured. Replay public data or bring back results from your assay.</p></div><div className="results-layout"><section className="results-card"><div className="results-card-header between"><h3>Your {records.length}-compound batch</h3><span className="badge">{latest.status}</span></div><div className="table-scroll"><table><thead><tr><th>Compound</th><th>Structure</th><th>Predicted</th><th>Observed</th><th>Difference</th></tr></thead><tbody>{records.map(r=>{const result=latest.results[r.compound_id];return <tr key={r.compound_id} className="result-row"><td className="mono">{short(r.compound_id)}</td><td><img src={molecule(r.compound_id)} alt={short(r.compound_id)}/></td><td>{fmt(r.prediction)}</td><td>{result?.status==='failed'?'Assay failed':fmt(result?.value)}</td><td>{result?.value!=null?fmt(result.value-r.prediction):'—'}</td></tr>;})}</tbody></table></div><div className="result-summary"><div><strong>{Object.keys(latest.results).length}/{records.length}</strong><small>outcomes recorded</small></div><div><strong>{fmt(mae)}</strong><small>mean absolute error · {campaign.endpoint}</small></div></div></section><aside><div className="results-controls">{campaign.demo&&<button className={resultMode==='replay'?'active':''} onClick={()=>setResultMode('replay')}>Public-data replay</button>}<button className={resultMode==='lab'?'active':''} onClick={()=>setResultMode('lab')}>Lab workflow</button></div><div className="replay-card">{resultMode==='replay'&&campaign.demo?<><div className="replay-glyph">▷</div><h3>Try the full loop, without a lab.</h3><p>Reveal the published measurements for your selected batch. These become saved observations in this campaign.</p><button className="btn primary" disabled={!!busy||latest.status==='complete'} onClick={reveal}>{latest.status==='complete'?'Measurements received ✓':busy||'Reveal public measurements →'}</button><small>Retrospective replay · no new experiment performed</small></>:<><h3>Bring back your lab results</h3><p>Use the template with compound_id,status,value. Values must already be {campaign.endpoint}. Partial imports and failed assays are supported.</p><a className="btn" href={`${base}/campaigns/${campaign.id}/rounds/${latest.round}/export?template=true`}>↓ Export result template</a><label className="file-drop">Import result CSV<input aria-label="Import result CSV" type="file" accept=".csv,text/csv" disabled={!!busy||latest.status==='complete'} onChange={e=>{const f=e.target.files?.[0];if(f)void importResults(f);e.target.value='';}}/></label></>}</div><div className="neutral-note"><strong>The handoff to a real lab</strong>Select → export → measure externally → import. Aster records observations; it does not run assays or order compounds.</div></aside></div><div className="results-actions"><span className="muted">This committed batch is saved. Its selection is now fixed.</span><button className="btn primary" disabled={latest.status!=='complete'||!!busy} onClick={()=>setStep('Learn')}>Learn from these results →</button></div></div>}
 {step==='Learn'&&campaign&&latest&&<div className="page"><div className="page-heading"><span className="eyebrow">Round {latest.round} / Learn</span><h1>Every result changes what comes next.</h1><p>Use the new evidence to make a better-informed next decision.</p></div><div className="learning-metrics"><div className="metric-card"><span>New measurements</span><strong>+{measuredResults.length}</strong><small>{measured.length} total measurements</small></div><div className="metric-card"><span>Batch prediction error</span><strong>{fmt(mae)}</strong><small>Mean absolute error · {campaign.endpoint}</small></div><div className="metric-card"><span>Still to explore</span><strong>{available.length}</strong><small>Eligible unmeasured compounds</small></div></div><div className="learn-layout"><section className="section-card"><h3>Expectation meets observation</h3><div className="learn-chart"><OutcomeChart points={measuredResults.map(r=>({id:r.compound_id,predicted:r.prediction,observed:latest.results[r.compound_id].value!}))} endpoint={campaign.endpoint}/></div><p className="muted">Selected-batch error is not an independent model-quality benchmark. Failed assays are excluded.</p></section><section className="section-card"><h3>{updated?'How remaining predictions changed':'What the next fit will use'}</h3>{updated?scores.filter(s=>s.compound_id in before).sort((a,b)=>Math.abs(b.prediction-before[b.compound_id])-Math.abs(a.prediction-before[a.compound_id])).slice(0,5).map(s=><div className="rank-change" key={s.compound_id}><strong>{short(s.compound_id)}</strong><span className="mono">{fmt(before[s.compound_id])} → {fmt(s.prediction)}</span><span>{fmt(s.prediction-before[s.compound_id])}</span></div>):<div className="learning-note"><strong>{measured.length} measured observations</strong><br/>Fit the model again using accumulated measurements, then rescore remaining candidates. Failed assays do not become training values.</div>}<div className="learning-note">More data can change the ranking in either direction. A changed prediction is not proof of a better model.</div></section></div><div className="learn-ready"><div><h3>{available.length?'Ready for your next discovery loop.':'Every eligible compound has been processed.'}</h3><p>{updated?'Review the updated shortlist and choose your next batch.':'Refit from the new observations to see what changed.'}</p></div><button className="btn primary" disabled={!!busy||!available.length} onClick={()=>updated?setStep('Select'):void predict(true)}>{busy|| (updated?'Select the next batch →':'Update the model →')}</button></div></div>}
 </main>}
 <dialog ref={dialog} onClose={()=>setComparison(null)} aria-labelledby="comparison-title"><div className="dialog-header"><div><span className="eyebrow">Inspect the evidence</span><h2 id="comparison-title">Compare compounds</h2></div><button className="btn" aria-label="Close comparison" onClick={()=>setComparison(null)}>✕</button></div><div className="dialog-tabs"><button className={comparison==='properties'?'active':''} onClick={()=>setComparison('properties')}>Properties</button><button className={comparison==='docking'?'active':''} onClick={()=>setComparison('docking')}>3D docking</button></div>{campaign&&comparison&&<div className="compare-grid" style={{'--columns':compare.length||1} as React.CSSProperties}>{compare.map(id=>{const s=scores.find(s=>s.compound_id===id);return <section className="comparison-card" key={id}><h3>{short(id)}</h3>{comparison==='docking'?<DockingView campaignId={campaign.id} compoundId={id} demo={campaign.demo}/>:<><img src={molecule(id)} alt={`${short(id)} molecular structure`} style={{width:'100%'}}/><MoleculeProperties campaignId={campaign.id} compoundId={id}/><div className="summary-line"><span>Predicted {campaign.endpoint}</span><strong>{fmt(s?.prediction)}</strong></div><div className="summary-line"><span>Nearest measured similarity</span><span>{fmt(s?.similarity)}</span></div><div className="summary-line"><span>Nearest measured compound</span><span>{short(s?.nearest_measured_id||'—')}</span></div><div className="summary-line"><span>Measured activity</span><span>{fmt(s?.nearest_measured_value)}</span></div></>}</section>;})}</div>}<div className="dialog-note">{comparison==='docking'?'Drag to rotate · Scroll to zoom. Experimental DAT structure: 8Y2G. Saved Vina poses are structural hypotheses; docking scores are not binding measurements.':'Compare up to three compounds using the comparison buttons in Select. Predictions are estimates, not measurements.'}</div></dialog>
 </div>;
}
function CandidateMap({scores,measured,selected,active,endpoint,onSelect}:{scores:Score[];measured:{id:string;value:number}[];selected:string[];active:string;endpoint:string;onSelect:(id:string)=>void}){
 const values=[...scores.map(s=>s.prediction),...measured.map(m=>m.value)],min=Math.floor(Math.min(3,...values)),max=Math.ceil(Math.max(10,...values)),x=(v:number)=>68+(v-min)/(max-min)*730,y=(v:number)=>385-v*360;
 return <svg viewBox="0 0 820 440" role="group" aria-label={`Candidate map: predicted ${endpoint} and chemical novelty`}>{Array.from({length:5},(_,i)=>{const v=min+(max-min)*i/4;return <g key={i}><path d={`M${x(v)} 25V385M68 ${y(i/4)}H798`} stroke="#e9e7eb"/><text x={x(v)} y="410" textAnchor="middle">{v.toFixed(1)}</text><text x="55" y={y(i/4)+4} textAnchor="end">{(i/4).toFixed(2)}</text></g>;})}<rect x="68" y="25" width="730" height="360" fill="none" stroke="#d8d4dc"/>{measured.map(m=><rect key={m.id} x={x(m.value)-3} y={382} width="6" height="6" fill="#56535d"><title>{short(m.id)}: observed {fmt(m.value)}</title></rect>)}{[...scores.filter(s=>s.compound_id!==active),...scores.filter(s=>s.compound_id===active)].map(s=>{const on=active===s.compound_id,pick=selected.includes(s.compound_id);return <g key={s.compound_id} role="button" tabIndex={0} aria-label={`Inspect ${short(s.compound_id)}, prediction ${fmt(s.prediction)}`} onClick={()=>onSelect(s.compound_id)} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onSelect(s.compound_id);}}}>{on&&<circle cx={x(s.prediction)} cy={y(1-s.similarity)} r="13" fill="#fff0af"/>}<circle cx={x(s.prediction)} cy={y(1-s.similarity)} r={on?7:pick?6:3.3} fill={on?'#a17b00':pick?'white':'#bdbac5'} stroke={pick||on?'#a17b00':'none'} strokeWidth="1.8"/><title>{short(s.compound_id)} · predicted {fmt(s.prediction)}</title></g>;})}<text x="68" y="435">Predicted {endpoint} → stronger activity</text><text transform="translate(16 220) rotate(-90)" textAnchor="middle">Novelty → farther from measured chemistry</text></svg>;
}
function OutcomeChart({points,endpoint}:{points:{id:string;predicted:number;observed:number}[];endpoint:string}){const min=Math.floor(Math.min(4,...points.flatMap(p=>[p.predicted,p.observed]))),max=Math.ceil(Math.max(10,...points.flatMap(p=>[p.predicted,p.observed]))),x=(v:number)=>45+(v-min)/(max-min)*430,y=(v:number)=>250-(v-min)/(max-min)*215;return <svg viewBox="0 0 510 295" role="img" aria-label="Predicted versus observed activity">{Array.from({length:5},(_,i)=>{const v=min+(max-min)*i/4;return <g key={i}><path d={`M${x(v)} 35V250M45 ${y(v)}H475`} stroke="#eeeaf3"/><text x={x(v)} y="270" textAnchor="middle">{v.toFixed(1)}</text><text x="30" y={y(v)+3} textAnchor="end">{v.toFixed(1)}</text></g>;})}<path d="M45 250L475 35" stroke="#d5b844" strokeDasharray="4 5"/>{points.map(p=><circle key={p.id} cx={x(p.predicted)} cy={y(p.observed)} r="5" fill="#c9a51d"><title>{short(p.id)}: predicted {fmt(p.predicted)}, observed {fmt(p.observed)}</title></circle>)}<text x="250" y="292" textAnchor="middle">Predicted {endpoint}</text><text transform="translate(12 140) rotate(-90)" textAnchor="middle">Observed {endpoint}</text></svg>;}

function MoleculeProperties({campaignId,compoundId}:{campaignId:string;compoundId:string}){const [data,setData]=useState<{mw:number;logp:number;tpsa:number}|null>(null),[failed,setFailed]=useState(false);useEffect(()=>{let live=true;api<{mw:number;logp:number;tpsa:number}>(`/campaigns/${campaignId}/molecule-properties?compound_id=${encodeURIComponent(compoundId)}`).then(d=>{if(live)setData(d);}).catch(()=>{if(live)setFailed(true);});return()=>{live=false;};},[campaignId,compoundId]);return <div className="descriptors">{failed?<span>Properties unavailable</span>:<><span>MW {data?data.mw.toFixed(1):'—'}</span><span>cLogP {data?data.logp.toFixed(1):'—'}</span><span>TPSA {data?data.tpsa.toFixed(1):'—'}</span></>}</div>;}
